$adminTitle='Refunds';require __DIR__.'/_header.php';require_once __DIR__.'/../includes/refunds.php';require_once __DIR__.'/../includes/notifications.php';$pdo=db();$ready=refunds_schema_ready($pdo);$error='';$orderId=(int)($_GET['order']??$_POST['order_id']??0);$refundId=(int)($_POST['refund_id']??0);
if($ready&&$_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_valid($_POST['csrf_token']??null))$error='Your session expired.';else{try{$action=(string)($_POST['action']??'request');if($action==='request'){$id=refund_request($pdo,$orderId,(float)($_POST['amount']??0),trim((string)($_POST['reason']??'')),(int)($_POST['payment_transaction_id']??0)?:null,(int)(admin_user()['id']??0)?:null);admin_audit($pdo,'refund.request','refund',(string)$id,'Recorded refund request',['order_id'=>$orderId,'amount'=>(float)($_POST['amount']??0)]);header('Location: refunds.php?order='.$orderId.'&requested='.$id);exit;}if($action==='processed'){refund_mark_processed($pdo,$refundId,trim((string)($_POST['gateway_reference']??'')),trim((string)($_POST['notes']??'')));admin_audit($pdo,'refund.process','refund',(string)$refundId,'Marked refund processed',['order_id'=>$orderId]);try{notify_refund_processed($pdo,$refundId);}catch(Throwable $mailError){error_log('Moleqra refund notification failed: '.$mailError->getMessage());}header('Location: refunds.php?order='.$orderId.'&processed=1');exit;}if($action==='reject'){$pdo->prepare("UPDATE order_refunds SET status='Rejected',notes=:notes WHERE id=:id AND status='Requested'")->execute(['notes'=>trim((string)($_POST['notes']??''))?:null,'id'=>$refundId]);admin_audit($pdo,'refund.reject','refund',(string)$refundId,'Rejected refund request',['order_id'=>$orderId]);header('Location: refunds.php?order='.$orderId.'&rejected=1');exit;}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Refund operation failed.';}}
}
$orders=$ready?$pdo->query("SELECT o.*,COALESCE((SELECT SUM(r.amount) FROM order_refunds r WHERE r.order_id=o.id AND r.status IN ('Requested','Processed')),0) refund_committed FROM sales_orders o WHERE o.payment_status IN ('Paid','Partially refunded','Refunded') ORDER BY o.created_at DESC LIMIT 300")->fetchAll():[];$order=null;$transactions=[];$refunds=[];if($orderId){foreach($orders as $o)if((int)$o['id']===$orderId)$order=$o;if($order){$s=$pdo->prepare('SELECT * FROM payment_transactions WHERE order_id=:id ORDER BY received_at DESC');$s->execute(['id'=>$orderId]);$transactions=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM order_refunds WHERE order_id=:id ORDER BY created_at DESC');$s->execute(['id'=>$orderId]);$refunds=$s->fetchAll();}}
?>
<div class="admin-heading"><div><div class="eyebrow">Finance</div><h1>Refunds</h1></div><a class="btn" href="payments.php">Payment reconciliation</a></div><?php if(!$ready):?><div class="alert error">V7 refund tracking is not installed.</div><?php endif;?><?php if(isset($_GET['requested'])):?><div class="alert success">Refund request recorded. Process the refund in PayFast, then mark it processed here.</div><?php endif;?><?php if(isset($_GET['processed'])):?><div class="alert success">Refund marked processed and customer receipt notification recorded.</div><?php endif;?><?php if(isset($_GET['rejected'])):?><div class="alert success">Refund request rejected.</div><?php endif;?><?php if($error):?><div class="alert error"><?= e($error) ?></div><?php endif;?>
