<?php if($order):?><section class="card admin-section-gap"><div class="section-heading"><div><h2><?= e($order['order_number']) ?></h2><p class="muted"><?= e($order['email']) ?> · Paid total <?= e($order['currency']) ?> <?= number_format((float)$order['grand_total'],2) ?></p></div><span class="status-pill"><?= e($order['payment_status']) ?></span></div><p><strong>Committed refunds:</strong> <?= e($order['currency']) ?> <?= number_format((float)$order['refund_committed'],2) ?> · <strong>Remaining:</strong> <?= e($order['currency']) ?> <?= number_format(max(0,(float)$order['grand_total']-(float)$order['refund_committed']),2) ?></p><?php if((float)$order['refund_committed']<(float)$order['grand_total']):?><form method="post" class="card"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="request"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><h3>Record refund request</h3><div class="form-grid"><div class="field"><label>Amount</label><input type="number" name="amount" min="0.01" max="<?= e((string)max(0,(float)$order['grand_total']-(float)$order['refund_committed'])) ?>" step="0.01" required></div><div class="field"><label>Payment transaction</label><select name="payment_transaction_id"><option value="">Unspecified</option><?php foreach($transactions as $t):?><option value="<?= (int)$t['id'] ?>"><?= e($t['gateway_payment_id'].' · '.$t['gateway_status']) ?></option><?php endforeach;?></select></div><div class="field full"><label>Reason</label><textarea name="reason" required></textarea></div></div><button class="btn primary">Record refund request</button></form><?php endif;?><h3>Refund history</h3><?php foreach($refunds as $r):?><article class="refund-record"><div><strong><?= e($r['refund_number']) ?></strong> · <?= e($r['currency']) ?> <?= number_format((float)$r['amount'],2) ?> · <?= e($r['status']) ?><p><?= e($r['reason']) ?></p></div><?php if($r['status']==='Requested'):?><div class="refund-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="processed"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><div class="field"><label>PayFast refund/reference</label><input name="gateway_reference"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><button class="btn primary">Mark processed</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="reject"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="notes" value="Rejected in admin"><button class="btn">Reject request</button></form></div><?php elseif($r['status']==='Processed'):?><a href="../refund-receipt.php?token=<?= e($order['order_token']) ?>&refund=<?= (int)$r['id'] ?>" target="_blank">Receipt</a><?php endif;?></article><?php endforeach;?><?php if(!$refunds):?><p class="muted">No refunds recorded.</p><?php endif;?></section><?php endif;?>
